const T = (sub, level, n) => `Number System · ${sub} · ${level} #${n}`;
const MP = (level, n) => T("Mixed Practice", level, n);
const WRONG = "Scan: wrong or unprovable answer";
const DUP = "Scan: repeats another question in the bank";
const rev = (n) => Number(String(n).split("").reverse().join(""));

